import{_ as e}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as t,o,f as a}from"./app-BUk7e3Lx.js";const i={},l=a('<h1 id="本地存储" tabindex="-1"><a class="header-anchor" href="#本地存储"><span>本地存储</span></a></h1><p>在前端开发中，偶尔需要存储一些如： 用户信息、登录状态、历史记录等常量数据。用于后续二次调用，并且避免刷新后丢失。这时，就需要用到本地存储了。</p><p>在 JavaScript 中，提供了四种可用的本地存储方式： cookie、localStorage、sessionStorage、 indexedDB （ 已废除的 WebSQL ）。</p><h2 id="_1-cookie" tabindex="-1"><a class="header-anchor" href="#_1-cookie"><span>1. cookie</span></a></h2><p>Cookie，类型为「小型文本文件」，指某些网站为了辨别用户身份而储存在用户本地终端上的数据。是为了解决 HTTP 无状态导致的问题。</p><p>作为一段一般不超过 4KB 的小型文本数据，它由一个名称（Name）、一个值（Value）和 其它几个用于控制 cookie 有效期、安全性、使用范围 的可选属性组成，以键值对的形式存储到本地。</p><p>但是 cookie 在每次请求中都会被发送，如果不使用 HTTPS 并对其加密，其保存的信息很容易被窃取，导致安全风险。举个例子，在一些使用 cookie 保持登录态的网站上，如果 cookie 被窃取，他人很容易利用你的 cookie 来假扮成你登录网站，所以需要对 Cookie 进行加密。</p><h2 id="_2-localstorage" tabindex="-1"><a class="header-anchor" href="#_2-localstorage"><span>2. localStorage</span></a></h2><p>HTML5 新方法，IE8 及以上浏览器都兼容。</p><p>特点：</p><ul><li>生命周期：持久化的本地存储，除非主动删除数据，否则数据是永远不会过期的。</li><li>存储的信息在同一域中是共享的。</li><li>当本页操作（新增、修改、删除）了 localStorage 的时候，本页面不会触发 storage 事件, 但是别的页面会触发 storage 事件。</li><li>大小：5M（跟浏览器厂商有关系）。</li><li>localStorage 本质上是对字符串的读取，如果存储内容多的话会消耗内存空间，会导致页面变卡。</li><li>受同源策略的限制。</li></ul><h2 id="_3-sessionstorage" tabindex="-1"><a class="header-anchor" href="#_3-sessionstorage"><span>3. sessionStorage</span></a></h2><p>sessionStorage 和 localStorage 使用方法基本一致，唯一不同的是生命周期，一旦页面（会话）关闭， sessionStorage 将会删除数据。</p><h2 id="_4-indexeddb" tabindex="-1"><a class="header-anchor" href="#_4-indexeddb"><span>4. indexedDB</span></a></h2><p>indexedDB 是一种低级 API，用于客户端存储大量结构化数据(包括, 文件/ blobs)。该 API 使用索引来实现对该数据的高性能搜索。</p><p>虽然 Web Storage 对于存储较少量的数据很有用，但对于存储更大量的结构化数据来说，这种方法不太有用。IndexedDB 提供了一个解决方案。</p><p>优点：</p><ul><li>储存量理论上没有上限。</li><li>所有操作都是异步的，相比 LocalStorage 同步操作性能更高，尤其是数据量较大时。</li><li>原生支持储存 JS 的对象。</li><li>是个正经的数据库，意味着数据库能干的事它都能干。</li></ul><p>缺点：</p><ul><li>操作非常繁琐。</li><li>本身有一定门槛。</li></ul><h2 id="_5-四种存储方式的区别" tabindex="-1"><a class="header-anchor" href="#_5-四种存储方式的区别"><span>5. 四种存储方式的区别</span></a></h2><table><thead><tr><th><strong>名称</strong></th><th><strong>存储大小</strong></th><th><strong>有效时间</strong></th><th><strong>数据与服务器之间的交互方式</strong></th><th><strong>访问策略</strong></th></tr></thead><tbody><tr><td>cookie</td><td>数据大小不能超过 4k</td><td>与设置的 cookie 过期时间有关，过期时间之前一直有效，即使窗口或浏览器关闭依然有效</td><td>cookie 的数据会自动的传递到服务器，服务器端也可以写 cookie 到客户端</td><td>符合同源策略可以访问</td></tr><tr><td>localStorage</td><td>一般为 5M，大小根据厂商不同有所差异（2.5M-10M 波动）</td><td>存储数据持久，浏览器关闭后数据不丢失，除非主动删除数据，否则数据一直存在</td><td>仅在本地保存，不与服务器交互</td><td>符合同源策略可以访问</td></tr><tr><td>sessionStorage</td><td>和 localStorage 一样</td><td>数据在当前浏览器窗口关闭后自动删除</td><td>仅在本地保存，不与服务器交互</td><td>即便符合同源策略也不可以相互访问</td></tr><tr><td>indexedDB</td><td>大于 250M</td><td>需手动更新或删除数据</td><td>仅在本地保存，不与服务器交互</td><td>符合同源策略可以访问</td></tr></tbody></table><h2 id="_6-应用场景" tabindex="-1"><a class="header-anchor" href="#_6-应用场景"><span>6. 应用场景</span></a></h2><p>在了解了上述的前端的缓存方式后，我们可以看看针对不对场景的使用选择：</p><ol><li>标记用户与跟踪用户行为的情况，推荐使用 cookie。</li><li>适合长期保存在本地的数据（令牌），推荐使用 localStorage。</li><li>敏感账号一次性登录，推荐使用 sessionStorage。</li><li>存储大量数据的情况、在线文档（富文本编辑器）保存编辑历史的情况，推荐使用 indexedDB。</li></ol>',25),r=[l];function s(d,n){return o(),t("div",null,r)}const h=e(i,[["render",s],["__file","本地存储.html.vue"]]),g=JSON.parse('{"path":"/JAVASCRIPT/%E6%9C%AC%E5%9C%B0%E5%AD%98%E5%82%A8.html","title":"本地存储","lang":"zh-CN","frontmatter":{"description":"本地存储 在前端开发中，偶尔需要存储一些如： 用户信息、登录状态、历史记录等常量数据。用于后续二次调用，并且避免刷新后丢失。这时，就需要用到本地存储了。 在 JavaScript 中，提供了四种可用的本地存储方式： cookie、localStorage、sessionStorage、 indexedDB （ 已废除的 WebSQL ）。 1. coo...","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/JAVASCRIPT/%E6%9C%AC%E5%9C%B0%E5%AD%98%E5%82%A8.html"}],["meta",{"property":"og:site_name","content":"🍑的博客 ！"}],["meta",{"property":"og:title","content":"本地存储"}],["meta",{"property":"og:description","content":"本地存储 在前端开发中，偶尔需要存储一些如： 用户信息、登录状态、历史记录等常量数据。用于后续二次调用，并且避免刷新后丢失。这时，就需要用到本地存储了。 在 JavaScript 中，提供了四种可用的本地存储方式： cookie、localStorage、sessionStorage、 indexedDB （ 已废除的 WebSQL ）。 1. coo..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-02-06T05:58:01.000Z"}],["meta",{"property":"article:author","content":"🍑"}],["meta",{"property":"article:modified_time","content":"2025-02-06T05:58:01.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"本地存储\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2025-02-06T05:58:01.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"🍑\\",\\"url\\":\\"https://mister-hope.com\\"}]}"]]},"headers":[{"level":2,"title":"1. cookie","slug":"_1-cookie","link":"#_1-cookie","children":[]},{"level":2,"title":"2. localStorage","slug":"_2-localstorage","link":"#_2-localstorage","children":[]},{"level":2,"title":"3. sessionStorage","slug":"_3-sessionstorage","link":"#_3-sessionstorage","children":[]},{"level":2,"title":"4. indexedDB","slug":"_4-indexeddb","link":"#_4-indexeddb","children":[]},{"level":2,"title":"5. 四种存储方式的区别","slug":"_5-四种存储方式的区别","link":"#_5-四种存储方式的区别","children":[]},{"level":2,"title":"6. 应用场景","slug":"_6-应用场景","link":"#_6-应用场景","children":[]}],"git":{"createdTime":1738821481000,"updatedTime":1738821481000,"contributors":[{"name":"taotao","email":"571596435@qq.com","commits":1}]},"readingTime":{"minutes":3.67,"words":1100},"filePathRelative":"JAVASCRIPT/本地存储.md","localizedDate":"2025年2月6日","excerpt":"\\n<p>在前端开发中，偶尔需要存储一些如： 用户信息、登录状态、历史记录等常量数据。用于后续二次调用，并且避免刷新后丢失。这时，就需要用到本地存储了。</p>\\n<p>在 JavaScript 中，提供了四种可用的本地存储方式： cookie、localStorage、sessionStorage、 indexedDB （ 已废除的 WebSQL ）。</p>\\n<h2>1. cookie</h2>\\n<p>Cookie，类型为「小型文本文件」，指某些网站为了辨别用户身份而储存在用户本地终端上的数据。是为了解决 HTTP 无状态导致的问题。</p>\\n<p>作为一段一般不超过 4KB 的小型文本数据，它由一个名称（Name）、一个值（Value）和 其它几个用于控制 cookie 有效期、安全性、使用范围 的可选属性组成，以键值对的形式存储到本地。</p>","autoDesc":true}');export{h as comp,g as data};
